parameters.jsCode:
const body = $input.item.json.body;
const roomAmount = Number(body.room_amount);
const incidentals = body.incidentals || [];
const payments = body.payments || [];

// GST Calculation
let gstRate = 0;
if (roomAmount > 1000 && roomAmount <= 7500) gstRate = 0.12;
else if (roomAmount > 7500) gstRate = 0.18;

const cgst = (roomAmount * (gstRate / 2)).toFixed(2);
const sgst = (roomAmount * (gstRate / 2)).toFixed(2);
const totalIncidentals = incidentals.reduce((sum, i) => sum + Number(i.amount), 0);
const totalCharges = (roomAmount + Number(cgst) + Number(sgst) + totalIncidentals).toFixed(2);

// Build HTML Rows
const incRows = incidentals.map(i => `<tr><td style="padding:8px;border-bottom:1px solid #eee">${i.description}</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">₹${Number(i.amount).toFixed(2)}</td></tr>`).join('');
const payRows = payments.map(p => `<tr><td style="padding:8px;border-bottom:1px solid #eee;color:#059669">Payment (${p.method})</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right;color:#059669">-₹${Number(p.amount).toFixed(2)}</td></tr>`).join('');

const htmlInvoice = `<html><body style="font-family:sans-serif;padding:40px;color:#333"><div style="text-align:center;border-bottom:2px solid #000;padding-bottom:20px"><h1>TAX INVOICE</h1><p>${body.property_name}</p></div><div style="margin-top:20px"><p><strong>Guest:</strong> ${body.guest_name}</p><p><strong>Room:</strong> ${body.room_number}</p><p><strong>Stay:</strong> ${body.check_in} to ${body.check_out}</p></div><table style="width:100%;margin-top:20px;border-collapse:collapse"><thead><tr style="background:#f4f4f4"><th align="left" style="padding:8px">Description</th><th align="right" style="padding:8px">Amount</th></tr></thead><tbody><tr><td style="padding:8px;border-bottom:1px solid #eee">Room Rate</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">₹${roomAmount.toFixed(2)}</td></tr>${incRows}<tr><td style="padding:8px">CGST (${(gstRate*50)}%)</td><td align="right">₹${cgst}</td></tr><tr><td style="padding:8px">SGST (${(gstRate*50)}%)</td><td align="right">₹${sgst}</td></tr><tr style="background:#fafafa"><td><strong>Total Charges</strong></td><td align="right"><strong>₹${totalCharges}</strong></td></tr>${payRows}</tbody><tfoot><tr><th align="left" style="padding:8px;font-size:18px">Balance Due</th><th align="right" style="padding:8px;font-size:18px">₹0.00</th></tr></tfoot></table><p style="margin-top:40px;font-size:10px;text-align:center;color:#999">HSN/SAC: 9963 | This is a system generated invoice.</p></body></html>`;

// Convert to Base64 for the Resend API
const base64Invoice = Buffer.from(htmlInvoice).toString('base64');

return {
  ...body,
  base64Invoice: base64Invoice
};

